INSERT INTO public.clinical_orders (order_code, folio_number, patient_alias, document_masked, eps_name, specialty, cups_code, cie10_code, procedure_name, center_city, attending_physician, status, priority, support_pdf_object, created_at, clinical_summary, patient_preparation, confidential) VALUES ('ORD-2026-1041', 'AUT-2026-008941', 'M. Rodriguez Vargas', 'CC ***4821', 'EPS Sanitas - Contributivo', 'Cardiologia Clinica', '881234', 'I10X - Hipertension esencial primaria', 'Ecocardiograma Transtoracico Doppler Color', 'Bogota', 'Dr. Alejandro Morales Pineda (RM 110284719)', 'AUTORIZADA', 'ALTA', 'soportes/2026/11/ORD-2026-1041.pdf', '2026-11-21 08:15:00-05', 'Paciente en seguimiento cardiovascular por hipertension arterial estadio II con disnea de medianos esfuerzos. Se solicita ecocardiograma transtoracico Doppler para cuantificar fraccion de eyeccion ventricular izquierda y descartar hipertrofia.', 'Presentarse 20 minutos antes de la cita con documento de identidad original y ultimo electrocardiograma de 12 derivaciones. No requiere ayuno previo. Continuar medicacion antihipertensiva habitual segun prescripcion.', 0) ON CONFLICT (order_code) DO UPDATE SET folio_number = EXCLUDED.folio_number, patient_alias = EXCLUDED.patient_alias, document_masked = EXCLUDED.document_masked, eps_name = EXCLUDED.eps_name, specialty = EXCLUDED.specialty, cups_code = EXCLUDED.cups_code, cie10_code = EXCLUDED.cie10_code, procedure_name = EXCLUDED.procedure_name, center_city = EXCLUDED.center_city, attending_physician = EXCLUDED.attending_physician, status = EXCLUDED.status, priority = EXCLUDED.priority, support_pdf_object = EXCLUDED.support_pdf_object, created_at = EXCLUDED.created_at, clinical_summary = EXCLUDED.clinical_summary, patient_preparation = EXCLUDED.patient_preparation, confidential = EXCLUDED.confidential;
INSERT INTO public.clinical_orders (order_code, folio_number, patient_alias, document_masked, eps_name, specialty, cups_code, cie10_code, procedure_name, center_city, attending_physician, status, priority, support_pdf_object, created_at, clinical_summary, patient_preparation, confidential) VALUES ('ORD-2026-1042', 'AUT-2026-008942', 'C. Restrepo Giraldo', 'CC ***9104', 'EPS Sura - Contributivo', 'Medicina Interna', '903895', 'E785 - Hiperlipidemia mixta en estudio', 'Panel Metabolico Basal y Perfil Lipidico Completo', 'Pereira', 'Dra. Camila Henao Salazar (RM 66104829)', 'PENDIENTE_FIRMA', 'MEDIA', 'soportes/2026/11/ORD-2026-1042.pdf', '2026-11-21 09:05:00-05', 'Control trimestral de programa de riesgo cardiometabolico en sede Eje Cafetero. Requiere determinacion serica de colesterol LDL, HDL, trigliceridos, glucemia basal y creatinina para ajuste de meta terapeutica con estatinas.', 'Ayuno estricto de 10 a 12 horas (solo se permite ingesta moderada de agua pura). Evitar consumo de alcohol o ejercicio fisico intenso durante las 24 horas previas a la puncion venosa en laboratorio clinico.', 0) ON CONFLICT (order_code) DO UPDATE SET folio_number = EXCLUDED.folio_number, patient_alias = EXCLUDED.patient_alias, document_masked = EXCLUDED.document_masked, eps_name = EXCLUDED.eps_name, specialty = EXCLUDED.specialty, cups_code = EXCLUDED.cups_code, cie10_code = EXCLUDED.cie10_code, procedure_name = EXCLUDED.procedure_name, center_city = EXCLUDED.center_city, attending_physician = EXCLUDED.attending_physician, status = EXCLUDED.status, priority = EXCLUDED.priority, support_pdf_object = EXCLUDED.support_pdf_object, created_at = EXCLUDED.created_at, clinical_summary = EXCLUDED.clinical_summary, patient_preparation = EXCLUDED.patient_preparation, confidential = EXCLUDED.confidential;
INSERT INTO public.clinical_orders (order_code, folio_number, patient_alias, document_masked, eps_name, specialty, cups_code, cie10_code, procedure_name, center_city, attending_physician, status, priority, support_pdf_object, created_at, clinical_summary, patient_preparation, confidential) VALUES ('ORD-2026-1043', 'AUT-2026-008943', 'L. Gomez Castellanos', 'CC ***3319', 'Compensar EPS - Contributivo', 'Neurologia Clinica', '883101', 'G439 - Cefalea cronica con signos de alerta', 'Resonancia Nuclear Magnetica de Cerebro Simple', 'Bogota', 'Dr. Mauricio Villamizar Duarte (RM 110391504)', 'AUTORIZADA', 'ALTA', 'soportes/2026/11/ORD-2026-1043.pdf', '2026-11-21 10:22:00-05', 'Cuadro de cefalea hemicraneana progresiva de 6 semanas de evolucion asociada a fosfenos transitorios. Examen neurologico focal sin deficit motor; se indica neuroimagen por resonancia magnetica simple para descartar lesion estructural.', 'Retirar todos los objetos metalicos, joyas, relojes y protesis removibles antes de ingresar al resonador. Diligenciar encuesta de seguridad magnetica (ausencia de marcapasos no condicional o implante ferromagnetico). No requiere ayuno.', 0) ON CONFLICT (order_code) DO UPDATE SET folio_number = EXCLUDED.folio_number, patient_alias = EXCLUDED.patient_alias, document_masked = EXCLUDED.document_masked, eps_name = EXCLUDED.eps_name, specialty = EXCLUDED.specialty, cups_code = EXCLUDED.cups_code, cie10_code = EXCLUDED.cie10_code, procedure_name = EXCLUDED.procedure_name, center_city = EXCLUDED.center_city, attending_physician = EXCLUDED.attending_physician, status = EXCLUDED.status, priority = EXCLUDED.priority, support_pdf_object = EXCLUDED.support_pdf_object, created_at = EXCLUDED.created_at, clinical_summary = EXCLUDED.clinical_summary, patient_preparation = EXCLUDED.patient_preparation, confidential = EXCLUDED.confidential;
INSERT INTO public.clinical_orders (order_code, folio_number, patient_alias, document_masked, eps_name, specialty, cups_code, cie10_code, procedure_name, center_city, attending_physician, status, priority, support_pdf_object, created_at, clinical_summary, patient_preparation, confidential) VALUES ('ORD-2026-1044', 'AUT-2026-008944', 'A. Vargas Ospina', 'CC ***7740', 'EPS Sura - Contributivo', 'Oncologia Clinica', '921801', 'C349 - Neoplasia pulmonar en estadificacion', 'Tomografia PET-CT Corporal Total con 18F-FDG', 'Medellin', 'Dra. Juliana Arboleda Mejia (RM 051298431)', 'EN_REVISION', 'ALTA', 'soportes/2026/11/ORD-2026-1044.pdf', '2026-11-22 11:40:00-05', 'Solicitud respaldada por Junta Medica Oncologica con confirmacion histopatologica previa para estadificacion metabolica ganglionar mediastinica y definicion de esquema quirurgico versus terapia sistemica dirigida.', 'Ayuno minimo de 6 horas antes de la inyeccion del radiofarmaco. Glucemia capilar previa obligatoria menor a 180 mg/dL. Dieta baja en carbohidratos y reposo fisico durante las 24 horas previas al estudio.', 0) ON CONFLICT (order_code) DO UPDATE SET folio_number = EXCLUDED.folio_number, patient_alias = EXCLUDED.patient_alias, document_masked = EXCLUDED.document_masked, eps_name = EXCLUDED.eps_name, specialty = EXCLUDED.specialty, cups_code = EXCLUDED.cups_code, cie10_code = EXCLUDED.cie10_code, procedure_name = EXCLUDED.procedure_name, center_city = EXCLUDED.center_city, attending_physician = EXCLUDED.attending_physician, status = EXCLUDED.status, priority = EXCLUDED.priority, support_pdf_object = EXCLUDED.support_pdf_object, created_at = EXCLUDED.created_at, clinical_summary = EXCLUDED.clinical_summary, patient_preparation = EXCLUDED.patient_preparation, confidential = EXCLUDED.confidential;
INSERT INTO public.clinical_orders (order_code, folio_number, patient_alias, document_masked, eps_name, specialty, cups_code, cie10_code, procedure_name, center_city, attending_physician, status, priority, support_pdf_object, created_at, clinical_summary, patient_preparation, confidential) VALUES ('ORD-2026-1045', 'AUT-2026-008945', 'D. Morales Caicedo', 'CC ***6052', 'Nueva EPS - Subsidiado', 'Endocrinologia', '890343', 'E119 - Diabetes mellitus tipo 2 alto riesgo renal', 'Junta Interdisciplinaria y Autorizacion Terapia Biologica', 'Cali', 'Dr. Andres Felipe Velasco (RM 76094182)', 'AUTORIZADA', 'MEDIA', 'soportes/2026/11/ORD-2026-1045.pdf', '2026-11-22 14:10:00-05', 'Falla terapeutica documentada a doble esquema oral con HbA1c en 8.9% y albuminuria persistente. Cumple criterios de escalonamiento farmacologico y registro en Cuenta de Alto Costo sin cobro de cuota moderadora.', 'Asistir con bitacora de glucometrias de los ultimos 14 dias y resultados vigentes de hemoglobina glicosilada y tasa de filtracion glomerular. Dispensacion sujeta a cadena de frio controlada entre 2 C y 8 C.', 0) ON CONFLICT (order_code) DO UPDATE SET folio_number = EXCLUDED.folio_number, patient_alias = EXCLUDED.patient_alias, document_masked = EXCLUDED.document_masked, eps_name = EXCLUDED.eps_name, specialty = EXCLUDED.specialty, cups_code = EXCLUDED.cups_code, cie10_code = EXCLUDED.cie10_code, procedure_name = EXCLUDED.procedure_name, center_city = EXCLUDED.center_city, attending_physician = EXCLUDED.attending_physician, status = EXCLUDED.status, priority = EXCLUDED.priority, support_pdf_object = EXCLUDED.support_pdf_object, created_at = EXCLUDED.created_at, clinical_summary = EXCLUDED.clinical_summary, patient_preparation = EXCLUDED.patient_preparation, confidential = EXCLUDED.confidential;
